"use strict";
const TYPES=["신설","증설","교체","안전환경","에너지"];
const CONDITIONS={operating:"가동 중 공사·조업중단 제약",building:"건축·구조물 변경",utility:"전력·용수 등 유틸리티 변경",external:"외부기관 협의·인허가 가능성",newtech:"신규 기술·검증 이력 부족",roof:"기존 건물 지붕 설치"};
const DOCS={proposal:"사업 제안서",drawing:"도면·배치도",quote:"견적서",operating:"운영 실적",spec:"설비 사양서",permit:"사전협의 자료"};
// Business questions below are design candidates, not certified standards.
const RULES=[
 ["R01","사업 필요성·미추진 영향","사업 필요성",[],[],"현재 문제와 미투자 시 영향을 확인합니다.",["proposal","operating"],"미투자 시 어떤 문제가 얼마나 발생하는가?","현황·필요성 설명서"],
 ["R02","대안 비교·선정 근거","대안 비교",[],["R01"],"현상 유지와 개조·신설 등 대안을 비교합니다.",["proposal","quote"],"더 적은 투자로 목적을 달성할 수 있는가?","대안 비교표"],
 ["R03","요구 성능·사업 범위","요구조건·범위",[],["R01"],"목표 성능과 포함·제외 범위를 명확히 합니다.",["proposal","spec"],"성능 목표를 어떤 자료로 검증할 것인가?","요구조건·범위 정의서"],
 ["R04","투자비 누락·산정 근거","투자비·자금",[],["R03"],"설비·공사·부대비용의 범위와 견적 근거를 확인합니다.",["quote","drawing"],"부대공사와 시험·교육 비용이 포함되었는가?","투자비 산출 내역"],
 ["R05","운영비·편익 가정 검토","경제성·편익",[],["R03"],"운영비와 기대효과의 산정 가정을 확인합니다.",["operating","spec"],"기대효과를 실제로 실현할 조건은 무엇인가?","비용·편익 가정표"],
 ["R06","경제성·비재무 편익 평가","경제성·편익",[],["R04","R05"],"투자 목적에 맞는 평가방법을 선정합니다.",["proposal","quote","operating"],"수익성 외에 어떤 편익과 의무를 고려해야 하는가?","경제성·편익 검토서"],
 ["R07","자금 확보·집행 계획","투자비·자금",[],["R04"],"시점별 자금 수요와 확보 가능성을 확인합니다.",["quote","proposal"],"필요한 시기에 투자 자금을 확보할 수 있는가?","자금 집행·확보 계획"],
 ["R08","목표 가동일 달성 가능성","일정 타당성",[],["R03"],"설계·조달·공사·시운전의 주요 제약을 검토합니다.",["proposal","spec"],"장납기품과 현장 제약을 일정에 반영했는가?","사업 실행 일정 검토서"],
 ["R09","주요 위험·민감도 검토","위험·종합 판단",[],["R06","R08"],"가정 변경과 주요 위험이 사업에 미치는 영향을 확인합니다.",["proposal","quote"],"비용 증가·효과 미달·지연 시 판단이 달라지는가?","위험·시나리오 검토표"],
 ["R10","운영·정비·인수 준비","운영 준비",[],["R03"],"운영 인력과 정비·인수 조건을 확인합니다.",["spec","operating"],"준공 후 성능을 유지하고 운영할 주체는 누구인가?","운영·성능 인수 검토서"],
 ["R11","승인 조건·미해결 사항","위험·종합 판단",[],["R07","R09","R10"],"승인 전 해소할 사항과 후속 확인 조건을 정리합니다.",["proposal"],"확인되지 않은 가정과 재심의 조건은 무엇인가?","종합 검토·조건 목록"],
 ["N01","입지·부지 적합성","부지·인허가·시공성",["신설"],["R03"],"신설 사업은 신규 입지의 적합성을 확인합니다.",["drawing","permit"],"부지 사용과 사업 추진을 제한하는 조건이 있는가?","입지·부지 검토서"],
 ["N02","신규 인프라 확보","기술 타당성",["신설"],["R03"],"신규 시설에 필요한 기반시설 확보를 검토합니다.",["drawing","spec"],"진입·전력·용수 등 인프라를 확보할 수 있는가?","인프라 수요·확보 검토표"],
 ["X01","기존 공정 병목·생산 균형","기술 타당성",["증설"],["R03"],"증설 효과가 다른 공정의 병목으로 제한되는지 확인합니다.",["operating","spec"],"증설 후 전후 공정 생산능력이 균형을 이루는가?","공정 생산능력 분석"],
 ["X02","기존 시설 연계·유틸리티 여력","기술 타당성",["증설"],["R03"],"기존 설비와 연결하고 유틸리티를 공급할 수 있는지 확인합니다.",["drawing","operating"],"기존 인프라의 여유 용량은 충분한가?","연계·용량 검토서"],
 ["P01","잔여수명·유지보수 대안","대안 비교",["교체"],["R01"],"교체 필요성을 고장·정비·수명 자료로 확인합니다.",["operating","quote"],"수리 또는 부분 교체가 더 적합하지 않은가?","교체·수리 비교표"],
 ["P02","철거·전환·조업중단 계획","부지·인허가·시공성",["교체"],["R03"],"기존 설비 철거와 신규 설비 전환 조건을 검토합니다.",["drawing","operating"],"전환 중 생산 차질을 얼마나 허용할 수 있는가?","전환·철거 검토서"],
 ["S01","안전환경 의무·개선 목표","요구조건·범위",["안전환경"],["R01"],"해소할 위험과 적용 의무의 원문을 확인합니다.",["proposal","permit"],"개선 목표와 의무 이행 수준은 무엇인가?","위험 현황·목표 정의서"],
 ["S02","개선 효과·잔여 위험","위험·종합 판단",["안전환경"],["S01","R03"],"개선 대책의 효과와 남는 위험을 검토합니다.",["spec","operating"],"투자 후에도 남는 위험에 대응할 수 있는가?","개선 효과·잔여 위험 검토서"],
 ["E01","에너지 사용 기준선","사업 필요성",["에너지"],["R01"],"현재 사용량과 운영조건을 기준선으로 정리합니다.",["operating"],"계절·가동률 변화가 사용량에 미친 영향은 무엇인가?","에너지 기준선 자료"],
 ["E02","발전·절감량과 성능 저하","경제성·편익",["에너지"],["E01","R03"],"운영 조건별 발전·절감량과 성능 변화를 검토합니다.",["spec","operating"],"예상 효과가 운영 조건과 성능 저하를 반영하는가?","에너지 효과 산정서"],
 ["C01","가동 중 시공·작업 안전","부지·인허가·시공성",["operating"],["R03"],"가동 중 공사 조건에서 생산·작업 간섭을 확인합니다.",["drawing","operating"],"공사와 생산을 병행할 수 있는가?","시공·조업 간섭 검토서"],
 ["C02","구조·건축 변경 적합성","기술 타당성",["building"],["R03"],"구조물 변경에 따른 기술 검증 범위를 확인합니다.",["drawing","spec"],"추가 하중과 구조 변경을 검증했는가?","구조·건축 전문가 검토"],
 ["C03","유틸리티 공급·접속 조건","기술 타당성",["utility"],["R03"],"유틸리티 변경에 따른 공급·접속 조건을 확인합니다.",["drawing","spec"],"공급 용량·접속 조건의 추가 협의가 필요한가?","유틸리티 협의·검토서"],
 ["C04","관할 인허가·외부 협의","부지·인허가·시공성",["external"],["R03"],"지역·규모·사업 조건에 따른 적용 절차를 확인합니다.",["permit","proposal"],"관할 기관의 최신 절차와 적용 조건을 확인했는가?","인허가 적용성 확인표"],
 ["C05","신규 기술 검증","기술 타당성",["newtech"],["R03"],"검증 이력이 부족한 기술의 시험·보증 조건을 확인합니다.",["spec"],"실증·시험으로 성능을 확인할 수 있는가?","기술 검증·시험 계획"],
 ["C06","지붕 구조·설치 적합성","기술 타당성",["roof"],["R03"],"기존 지붕 설치 조건에서 구조·배치 적합성을 확인합니다.",["drawing","spec"],"배치와 하중에 대한 전문가 검토가 필요한가?","지붕 설치 적합성 검토"]
].map(([id,title,category,when,deps,reason,docs,question,deliverable])=>({id,title,category,when,deps,reason,docs,question,deliverable}));
let type="증설", plan=null, records=[], formDirty=false, typeValues={};
const $=id=>document.getElementById(id);
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function toast(s){$("toast").textContent=s;$("toast").classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>$("toast").classList.remove("show"),3500)}
function renderTypes(){ $("type-options").innerHTML=TYPES.map(t=>`<button type="button" data-type="${t}" class="${type===t?"active":""}" aria-pressed="${type===t}">${t}</button>`).join(""); renderTypeInputs(); }
function renderTypeInputs(){const t=TYPE_IO[type];$("type-inputs").innerHTML=`<details class="type-input-box" open><summary>${type} 사업 · 상세 인풋 <small>미입력 시 확인 필요</small></summary><p>${esc(t.focus)}</p>${t.fields.map(([key,label,hint])=>`<label>${esc(label)}<textarea data-typefield="${key}" id="type-${key}" rows="2" placeholder="${esc(hint)}">${esc(typeValues[type]?.[key]||"")}</textarea></label>`).join("")}</details>`}
$("type-inputs").addEventListener("input",e=>{if(e.target.dataset.typefield){(typeValues[type]??={})[e.target.dataset.typefield]=e.target.value}});
renderTypes();
$("conditions").innerHTML=Object.entries(CONDITIONS).map(([k,v])=>`<label class="check"><input type="checkbox" id="cond-${k}">${v}</label>`).join("");
$("documents").innerHTML=Object.entries(DOCS).map(([k,v])=>`<label class="check"><input type="checkbox" id="doc-${k}">${v}</label>`).join("");
function projectInput(){const v={type};["name","purpose","location","budget","scale","start","target"].forEach(k=>v[k]=$(k).value.trim());v.conditions=Object.keys(CONDITIONS).filter(k=>$("cond-"+k).checked);v.docs=Object.keys(DOCS).filter(k=>$("doc-"+k).checked);v.typeInputs={...(typeValues[type]||{})};return v}
function fill(p){type=p.type;if(p.typeInputs)typeValues[type]={...p.typeInputs};renderTypes();["name","purpose","location","budget","scale","start","target"].forEach(k=>$(k).value=p[k]||"");Object.keys(CONDITIONS).forEach(k=>$("cond-"+k).checked=p.conditions.includes(k));Object.keys(DOCS).forEach(k=>$("doc-"+k).checked=p.docs.includes(k))}
function persist(){try{localStorage.setItem("investment-review-v1",JSON.stringify({form:projectInput(),plan,records,typeValues,criteriaVersion:CRITERIA_VERSION}));return true}catch{toast("브라우저 저장 공간을 사용할 수 없습니다. CSV로 보관하세요.");return false}}
function invalidate(){if(plan){plan.confirmed=false;formDirty=true;$("plan-status").textContent="조건 변경 · 재도출 필요";$("confirm").disabled=true;$("confirm-message").textContent="사업 조건이 변경되었습니다. 검토항목을 다시 도출하세요."}}
$("type-options").addEventListener("click",e=>{if(!e.target.dataset.type)return;type=e.target.dataset.type;renderTypes();invalidate()});
$("project-form").addEventListener("input",invalidate);
function buildItems(p,previous){return RULES.map(r=>{const match=!r.when.length||r.when.includes(p.type)||r.when.some(c=>p.conditions.includes(c));const status=match?"적용":r.id.startsWith("C")?"판단 보류":"제외";const old=previous?.find(x=>x.id===r.id);return {...r,status,reason:match?r.reason:status==="제외"?`${p.type} 유형과 다른 유형에 해당하는 기준입니다.`:"해당 현장 조건이 선택되지 않았습니다. 적용 여부를 담당자가 확인해야 합니다.",owner:old?.owner||"",days:old?.days||"",durationBasis:old?.durationBasis||"",review:"미착수",reviewed:false,changeReason:old?.changeReason||"",source:old?.source||"",inputNotes:old?.inputNotes||"",outputNotes:old?.outputNotes||"",extraDeps:[]}})}
function generate(e){e?.preventDefault();if(!$("project-form").reportValidity())return;const p=projectInput();if(p.start&&p.target&&p.start>p.target){toast("목표 심의일은 검토 시작일 이후여야 합니다.");return}const unchanged=plan&&JSON.stringify(plan.project)===JSON.stringify(p);if(unchanged){toast("입력 조건이 동일하여 기존 검토 내용을 유지했습니다.");return}plan={project:p,items:buildItems(p,plan?.items),confirmed:false,version:1,created:new Date().toISOString()};formDirty=false;renderPlan();persist();toast("사업 조건에 따른 검토 초안을 도출했습니다.")}
$("project-form").addEventListener("submit",generate);
function sample(){if(plan&&!confirm("현재 계획을 증설사업 예시로 바꿀까요? 현재 편집 내용이 대체됩니다."))return;fill({type:"증설",name:"2공장 생산라인 증설",purpose:"수요 증가 대응 및 생산 병목 해소",location:"울산 2공장",budget:"35",scale:"연간 생산능력 2만 톤 증대",start:"2026-10-26",target:"2026-12-18",conditions:["operating","utility"],docs:["proposal","operating","drawing"]});plan=null;generate()}
$("sample").onclick=sample;$("empty-sample").onclick=sample;
const applied=()=>plan.items.filter(i=>i.status==="적용");
function missing(i){return i.docs.filter(d=>!plan.project.docs.includes(d))}
function renderPlan(){
 $("empty").hidden=true;$("generated").hidden=false;$("step2").classList.add("on");$("step3").classList.toggle("on",plan.confirmed);
 $("result-title").textContent=plan.project.name;$("result-subtitle").textContent=`${plan.project.type} · ${plan.project.location} · ${plan.project.budget?plan.project.budget+"억원":"투자비 미정"} · v${plan.version}`;
 $("plan-status").textContent=plan.confirmed?"담당자 확인 · 계획 확정":"검토 초안";$("plan-status").className="badge"+(plan.confirmed?"":" amber");
 const items=applied();$("stats").innerHTML=`<div class="stat"><small>적용 검토항목</small><strong>${items.length}<span>개</span></strong></div><div class="stat"><small>적용 판단 보류</small><strong>${plan.items.filter(i=>i.status==="판단 보류").length}<span>개</span></strong></div><div class="stat"><small>기간 확인 필요</small><strong>${items.filter(i=>!validDays(i)).length}<span>개</span></strong></div>`;
 $("confirm").disabled=plan.confirmed||formDirty;$("confirm").textContent=plan.confirmed?"확정 완료":"검토계획 확정";
 $("confirm-message").textContent=plan.confirmed?"계획이 확정되었습니다. 이는 투자 승인 또는 검토 완료를 뜻하지 않습니다.":"항목별 적용 판단·담당·기간과 준비자료를 확인한 후 확정하세요.";
 renderItems();renderSchedule();renderRequests();renderIO();$("actual-project").value=plan.project.name;
 if(formDirty)invalidate();
}
function renderItems(){const q=$("search").value.trim().toLowerCase(), f=$("filter").value;
 const items=plan.items.filter(i=>(f==="all"||i.status===f)&&[i.title,i.category,ITEM_DETAILS[i.id].topic,...ITEM_DETAILS[i.id].inputs,...ITEM_DETAILS[i.id].outputs,...i.docs.map(d=>DOCS[d])].join(" ").toLowerCase().includes(q));
 $("item-list").innerHTML=items.map(i=>`<article class="item"><div class="item-top"><div class="item-title"><span class="item-id">${i.id}</span><h3>${esc(i.title)}</h3></div><span class="badge ${i.status==="판단 보류"?"amber":i.status==="제외"?"gray":""}">${i.status}</span></div><p>${esc(i.reason)}</p><p class="kpc-topic">KPC 관련 영역 · ${esc(ITEM_DETAILS[i.id].topic)} <span>${ITEM_DETAILS[i.id].relation}</span></p><div class="io-mini"><div><b>IN</b>${esc(ITEM_DETAILS[i.id].inputs[0])} 외 ${ITEM_DETAILS[i.id].inputs.length-1}개</div><div><b>OUT</b>${esc(ITEM_DETAILS[i.id].outputs[0].split(":")[0])}</div></div><div class="item-bottom"><span class="chip">${i.category}</span><span>${i.status==="적용"?`자료 ${i.docs.length-missing(i).length}/${i.docs.length} · ${validDays(i)?esc(i.days)+" 영업일":"기간 미산정"}`:"적용성 확인"}</span>${i.reviewed?'<span>✓ 담당자 확인</span>':""}<button data-detail="${i.id}">상세 검토 ↗</button></div></article>`).join("")||'<div class="empty-line">검색 조건에 맞는 항목이 없습니다.</div>';
}
$("search").oninput=renderItems;$("filter").onchange=renderItems;
$("item-list").onclick=e=>{if(e.target.dataset.detail)openDetail(e.target.dataset.detail)};
function openDetail(id){const i=plan.items.find(x=>x.id===id);
 $("detail-body").innerHTML=`<span class="eyebrow">${i.id} · ${i.category}</span><h2>${esc(i.title)}</h2><div class="detail-note"><b>추천 이유</b>${esc(i.reason)}<b>확인 질문</b>${esc(i.question)}<b>필요 산출물</b>${esc(i.deliverable)}</div><div class="detail-note"><b>필요자료</b>${i.docs.map(d=>`${plan.project.docs.includes(d)?"✓":"○"} ${DOCS[d]}`).join(" · ")}<b>선행 검토</b>${i.deps.map(d=>RULES.find(x=>x.id===d).title).join(", ")||"없음"}<b>근거 상태</b>설계 예시 · 사내 검증 전. 적용 전문기준·원문 근거를 추가해야 합니다.</div>
 <form id="detail-form"><div class="detail-grid"><label>적용 여부<select id="edit-status">${["적용","판단 보류","제외"].map(s=>`<option ${s===i.status?"selected":""}>${s}</option>`).join("")}</select></label><label>검토 진행<select id="edit-review">${["미착수","검토 중","완료"].map(s=>`<option ${s===i.review?"selected":""}>${s}</option>`).join("")}</select></label></div><label>담당자·부서<input id="edit-owner" value="${esc(i.owner)}" placeholder="예: 생산기술팀"></label><div class="detail-grid"><label>예상기간 (영업일)<input id="edit-days" type="number" min="1" max="3650" step="1" value="${esc(i.days)}" placeholder="미산정"></label><label>기간 근거<input id="edit-basis" value="${esc(i.durationBasis)}" placeholder="예: 담당자 추정, 과거 실적"></label></div><label>원문 근거·결과 위치<input id="edit-source" value="${esc(i.source)}" placeholder="문서명·페이지·조항 또는 URL"></label><label>판단·수정 사유<textarea id="edit-reason" rows="2" placeholder="적용·제외 판단 및 수정 사유">${esc(i.changeReason)}</textarea></label><label class="check"><input id="edit-reviewed" type="checkbox" ${i.reviewed?"checked":""}>담당자가 적용 여부와 근거·확인사항을 검토함</label><p class="micro">자료 보유 체크만으로 증빙의 적정성이 검증되지는 않습니다.</p><button class="button primary">항목 저장</button></form>`;
 $("detail-body").insertAdjacentHTML("afterbegin",detailHTML(i.id,plan.project.type));
 $("detail-form").insertAdjacentHTML("afterbegin",`<label>인풋 확보 내용·자료 위치<textarea id="edit-input-notes" rows="3" placeholder="아래 필요 인풋의 실제 값·단위·기준일·문서 위치를 기록하세요">${esc(i.inputNotes||"")}</textarea></label><label>아웃풋 작성 결과·문서 위치<textarea id="edit-output-notes" rows="3" placeholder="검토 결론과 작성한 산출물의 위치">${esc(i.outputNotes||"")}</textarea></label>`);
 $("detail").showModal();
 $("detail-form").onsubmit=e=>{e.preventDefault();if($("edit-days").value&&!$("edit-basis").value.trim()){toast("예상기간의 근거를 입력하세요.");return}if(($("edit-status").value!==i.status||$("edit-reviewed").checked)&&!$("edit-reason").value.trim()){toast("적용 판단 또는 확인 사유를 입력하세요.");return}if($("edit-review").value==="완료"&&!$("edit-source").value.trim()){toast("검토 완료의 근거 문서·결과 위치를 입력하세요.");return}
 if($("edit-review").value==="완료"&&(!$("edit-input-notes").value.trim()||!$("edit-output-notes").value.trim())){toast("완료 처리에는 인풋 확인 내용과 산출물 작성 결과가 필요합니다.");return}
 Object.assign(i,{status:$("edit-status").value,review:$("edit-review").value,owner:$("edit-owner").value.trim(),days:$("edit-days").value,durationBasis:$("edit-basis").value.trim(),source:$("edit-source").value.trim(),changeReason:$("edit-reason").value.trim(),reviewed:$("edit-reviewed").checked,inputNotes:$("edit-input-notes").value.trim(),outputNotes:$("edit-output-notes").value.trim()});
 plan.confirmed=false;plan.version++;$("detail").close();renderPlan();persist();toast("항목을 저장하고 계획을 갱신했습니다.");};
}
document.querySelector(".close-dialog").onclick=()=>$("detail").close();
function validDays(i){return Number.isInteger(Number(i.days))&&Number(i.days)>0&&Number(i.days)<=3650&&!!i.durationBasis}
function dateAt(s,n){const d=new Date(s+"T12:00:00");if(isNaN(d))return null;while(d.getDay()===0||d.getDay()===6)d.setDate(d.getDate()+1);for(let k=0;k<n;k++){d.setDate(d.getDate()+1);while(d.getDay()===0||d.getDay()===6)d.setDate(d.getDate()+1)}return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`}
function schedule(){const items=applied(), ends={}, starts={}, ownerEnd={}, pending=[...items], errors=[];let iterations=0;
 while(pending.length&&iterations++<RULES.length+1){let advanced=false;for(let k=0;k<pending.length;k++){const i=pending[k];if(i.deps.some(d=>pending.some(p=>p.id===d)))continue;
 const blocked=i.deps.filter(d=>!items.some(p=>p.id===d)||ends[d]==null);
 if(!validDays(i)||!i.owner||blocked.length){ends[i.id]=null;errors.push(i.id)}else{starts[i.id]=Math.max(0,ownerEnd[i.owner]||0,...i.deps.map(d=>ends[d]));ends[i.id]=starts[i.id]+Number(i.days);ownerEnd[i.owner]=ends[i.id]}
 pending.splice(k--,1);advanced=true}if(!advanced)break}
 return {starts,ends,errors:[...errors,...pending.map(i=>i.id)],total:Math.max(0,...Object.values(ends).filter(x=>x!=null))};}
function renderSchedule(){const s=schedule(),p=plan.project, missingDocs=applied().some(i=>missing(i).length),all=s.errors.length===0&&!!p.start&&!missingDocs;const end=all?dateAt(p.start,s.total-1):null;
 $("view-schedule").innerHTML=`<h2>승인 전 검토 일정</h2><p>${all?`예상 검토 완료 <b>${end}</b> · ${s.total} 영업일${p.target&&end>p.target?" · 목표 심의일 초과":""}`:"전체 검토기간 미산정 · 아래 선행조건을 보완하세요."}</p><div class="notice"><b>계산 조건</b><span>월–금 영업일 기준, 공휴일 미반영. 같은 담당자·부서는 한 번에 한 작업을 수행하고 서로 다른 담당자는 병행합니다. 자료 준비·외부 대기기간은 항목 기간에 포함해 입력하세요. 미확보 자료가 있으면 전체 일정 확정을 보류합니다.</span></div>${!p.start?'<p>• 검토 시작일을 입력하세요.</p>':""}${missingDocs?'<p>• 자료 요청 탭에서 미확보 자료를 확인하세요.</p>':""}${applied().map(i=>`<div class="task-row"><b>${i.id} · ${esc(i.title)}</b><span>${i.owner?esc(i.owner):"담당 미정"} · ${s.ends[i.id]!=null?`${s.starts[i.id]+1}~${s.ends[i.id]}일차${p.start?" / "+dateAt(p.start,s.starts[i.id])+" ~ "+dateAt(p.start,s.ends[i.id]-1):""}`:"미산정: 기간·담당·선행 항목 확인"}</span><br><span>선행: ${i.deps.join(", ")||"없음"} · ${esc(i.durationBasis||"기간 근거 미등록")}</span></div>`).join("")}`;
}
function renderRequests(){const needs={};applied().forEach(i=>missing(i).forEach(d=>(needs[d]??=[]).push(i)));
 $("view-requests").innerHTML=`<h2>자료 준비·요청 목록</h2><p class="micro">자료를 확보하면 왼쪽 보유 자료를 체크한 뒤 다시 도출하세요. 새 도출 시 적용 판단·검토 상태는 재확인이 필요합니다.</p>${Object.entries(needs).map(([d,items])=>`<div class="request-row"><b>○ ${DOCS[d]}</b><p>관련 항목: ${items.map(i=>esc(i.title)).join(", ")}</p></div>`).join("")||'<p>입력한 보유 여부 기준으로 누락 자료가 없습니다. 실제 증빙의 적정성은 별도 확인이 필요합니다.</p>'}`;
}
document.querySelectorAll("[data-view]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-view]").forEach(x=>x.classList.toggle("active",x===b));["items","io","schedule","requests"].forEach(v=>$("view-"+v).hidden=v!==b.dataset.view)});
$("confirm").onclick=()=>{const pending=plan.items.filter(i=>i.status==="판단 보류"||!i.reviewed);if(pending.length){toast(`${pending.length}개 항목의 적용 판단·담당자 확인을 먼저 완료하세요.`);return}if(!applied().length){toast("적용 검토항목이 한 개 이상 필요합니다.");return}const s=schedule();if(!plan.project.start||s.errors.length||applied().some(i=>missing(i).length)){toast("시작일·담당·기간·선행조건·미확보 자료를 보완하세요.");return}if(!confirm("담당자가 검토한 계획으로 확정할까요? 실제 투자 승인은 별도 심의입니다."))return;plan.confirmed=true;plan.version++;renderPlan();persist();toast("검토계획을 확정했습니다.");};
$("save").onclick=()=>{if(persist())toast("이 브라우저에 저장했습니다.")};
function csvCell(v){let s=String(v??"");if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
$("export").onclick=()=>{const rows=exportRows();const blob=new Blob(["\ufeff"+rows.map(r=>r.map(csvCell).join(",")).join("\r\n")],{type:"text/csv;charset=utf-8"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="투자사업_검토계획_KPC_IO.csv";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast("검토항목·인풋·아웃풋·출처를 CSV로 내보냈습니다.");};
document.querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-page]").forEach(x=>x.classList.toggle("active",b===x));document.querySelectorAll(".page").forEach(p=>p.classList.toggle("active",p.id==="page-"+b.dataset.page));$("breadcrumb").textContent={plan:"사업별 검토계획",criteria:"검토기준 라이브러리",results:"수행 결과·개선"}[b.dataset.page]});
$("library").innerHTML=`<table><thead><tr><th>ID</th><th>검토항목 / KPC 관련영역</th><th>적용 조건</th><th>인풋 → 아웃풋</th><th>출처·구체항목</th></tr></thead><tbody>${RULES.map(r=>`<tr><td>${r.id}</td><td><b>${r.title}</b><br>${ITEM_DETAILS[r.id].topic}</td><td>${r.when.map(c=>CONDITIONS[c]||c).join(", ")||"모든 사업 공통"}</td><td>${esc(ITEM_DETAILS[r.id].inputs[0])}<br>→ ${esc(ITEM_DETAILS[r.id].outputs[0].split(":")[0])}</td><td><button class="button small" data-library-detail="${r.id}">상세 보기</button></td></tr>`).join("")}</tbody></table>`;
$("library").onclick=e=>{const id=e.target.dataset.libraryDetail;if(!id)return;$("detail-body").innerHTML=`<h2>${esc(RULES.find(r=>r.id===id).title)}</h2>${detailHTML(id,$("library-type").value)}`;$("detail").showModal()};
$("library-type").onchange=()=>{$("library-type-io").innerHTML=typeSummary($("library-type").value)};
$("library-type-io").innerHTML=typeSummary("증설");
$("actual-item").innerHTML=RULES.map(i=>`<option value="${i.id}">${i.id} · ${i.title}</option>`).join("");
function renderRecords(){$("record-count").textContent=records.length+"건";$("records").innerHTML=records.map(r=>`<article class="panel record"><span class="badge amber">표준 반영 전 · 개선 후보</span><p><b>${esc(r.project)} · ${esc(RULES.find(i=>i.id===r.item)?.title||r.item)}</b></p><time>${esc(r.start)} ~ ${esc(r.end)}</time><p>${esc(r.result)}</p>${r.improvement?`<div class="detail-note"><b>개선 제안</b>${esc(r.improvement)}</div>`:""}</article>`).join("")||'<div class="panel empty-line">아직 기록된 수행 결과가 없습니다.</div>'}
$("feedback-form").onsubmit=e=>{e.preventDefault();if($("actual-start").value>$("actual-end").value){toast("완료일은 시작일 이후여야 합니다.");return}records.unshift({project:$("actual-project").value.trim(),item:$("actual-item").value,start:$("actual-start").value,end:$("actual-end").value,result:$("actual-result").value.trim(),improvement:$("actual-improvement").value.trim()});persist();renderRecords();$("actual-result").value="";$("actual-improvement").value="";toast("개별 사례·개선 후보로 저장했습니다. 표준은 자동 변경되지 않습니다.");};
try{const s=JSON.parse(localStorage.getItem("investment-review-v1"));if(s?.typeValues)typeValues=s.typeValues;if(s?.form)fill(s.form);if(Array.isArray(s?.records))records=s.records;if(s?.plan?.items?.length){plan=s.plan;formDirty=JSON.stringify(s.form)!==JSON.stringify(plan.project);if(s.criteriaVersion!==CRITERIA_VERSION){plan.confirmed=false;plan.items.forEach(i=>i.reviewed=false);toast("기존 입력·기록은 유지했습니다. 구체화된 기준에 대한 담당자 재확인이 필요합니다.")}renderPlan()}}catch{toast("저장 데이터를 읽지 못했습니다. 새 계획을 시작하세요.")}
renderRecords();
function listHTML(values){return `<ul>${values.map(v=>`<li>${esc(v)}</li>`).join("")}</ul>`}
function typeSummary(t){const profile=TYPE_IO[t];return `<div class="type-summary"><p><b>${t} · ${esc(profile.focus)}</b></p><div class="io-columns"><div><span class="io-label">필요 인풋</span>${listHTML(profile.fields.map(f=>f[1]+" — "+f[2]))}</div><div><span class="io-label">작성할 아웃풋</span>${listHTML(profile.outputs)}</div></div><p>${esc(profile.rule)}</p><small>유형별 데이터와 산출물은 KPC 공개 교육영역을 참고한 실무 설계안입니다.</small></div>`}
function detailHTML(id,t){const d=ITEM_DETAILS[id],s=KPC_SOURCES[d.source];return `<div class="kpc-detail"><p class="kpc-topic">KPC 관련 영역 · ${esc(d.topic)} <span>${d.relation}</span></p><div class="source-note"><a href="${s.url}" target="_blank" rel="noreferrer">${esc(s.title)} ↗</a><p>${esc(s.scope)} · 확인일 ${s.checked}</p><small>KPC 공개 교육영역을 참고한 대응입니다. 아래 상세 인풋·작업·산출물·확인기준은 이 시스템의 실무 확장안이며 KPC 공식 업무표준이 아닙니다.</small></div><div class="io-columns"><div><span class="io-label">INPUT · 필요한 데이터</span>${listHTML(d.inputs)}</div><div><span class="io-label">WORK · 검토할 업무</span>${listHTML(d.checks)}</div></div><div class="detail-note"><b>OUTPUT · 산출물과 포함 필드</b>${listHTML(d.outputs)}<b>검토 완료 시 확인할 내용</b>${esc(d.acceptance)}</div><div class="detail-note"><b>${t} 유형 적용 시</b>${esc(TYPE_IO[t].rule)}</div></div>`}
function renderIO(){const t=plan.project.type,p=TYPE_IO[t],values=plan.project.typeInputs||{};$("view-io").innerHTML=`<div class="panel">${typeSummary(t)}<h2>현재 사업의 입력 현황</h2>${p.fields.map(([k,l])=>`<div class="request-row"><b>${esc(l)} <span class="badge ${values[k]?.trim()?"":"amber"}">${values[k]?.trim()?"입력됨 · 근거 확인 필요":"확인 필요"}</span></b><p class="preserve">${esc(values[k]||"미입력 — 담당자에게 자료를 요청하세요.")}</p></div>`).join("")}</div><h2 class="records-title">적용 항목별 데이터 연결</h2>${applied().map(i=>`<details class="panel io-card"><summary>${i.id} · ${esc(i.title)}</summary>${detailHTML(i.id,t)}<p><b>기록한 인풋:</b> ${esc(i.inputNotes||"미등록")}</p><p><b>작성한 아웃풋:</b> ${esc(i.outputNotes||"미등록")}</p><button class="button small" data-io-detail="${i.id}">내용 기록·수정</button></details>`).join("")}`;$("view-io").onclick=e=>{if(e.target.dataset.ioDetail)openDetail(e.target.dataset.ioDetail)};
 const missingFields=p.fields.filter(([k])=>!values[k]?.trim());$("view-requests").insertAdjacentHTML("beforeend",`<h2 class="records-title">유형별 추가 인풋 확인</h2>${missingFields.length?missingFields.map(([,l,h])=>`<div class="request-row"><b>${esc(l)}</b><p>${esc(h)}</p></div>`).join(""):"<p>유형별 입력란을 작성했습니다. 실제 증빙은 담당자 확인이 필요합니다.</p>"}<h2 class="records-title">세부 자료 요청 목록</h2>${applied().map(i=>`<details class="request-row"><summary>${i.id} · ${esc(i.title)} — ${i.inputNotes?"확보 내용 기록됨":"확보 내용 미등록"}</summary>${listHTML(ITEM_DETAILS[i.id].inputs)}</details>`).join("")}`);
}
function exportRows(){const headers=["사업명","사업유형","기준버전","계획상태","ID","영역","검토항목","적용여부","적용이유","필요자료","미확보자료","확인질문","산출물","선행항목","담당","영업일","기간근거","검토진행","담당자확인","원문근거","판단사유","KPC 관련영역","대응구분","KPC 출처","확인일","필요 인풋","검토작업","상세 아웃풋","완료 확인기준","유형별 인풋 값","유형별 아웃풋","인풋 확보 기록","아웃풋 작성 기록"];
 return [headers,...plan.items.map(i=>{const d=ITEM_DETAILS[i.id],s=KPC_SOURCES[d.source];return [plan.project.name,plan.project.type,CRITERIA_VERSION,formDirty?"조건 변경·재도출 필요":plan.confirmed?"계획 확정":"초안",i.id,i.category,i.title,i.status,i.reason,i.docs.map(d=>DOCS[d]).join(" / "),missing(i).map(d=>DOCS[d]).join(" / "),i.question,i.deliverable,i.deps.join(" / "),i.owner,i.days,i.durationBasis,i.review,i.reviewed?"확인":"미확인",i.source,i.changeReason,d.topic,d.relation,s.url,s.checked,d.inputs.join(" / "),d.checks.join(" / "),d.outputs.join(" / "),d.acceptance,TYPE_IO[plan.project.type].fields.map(([k,l])=>l+": "+(plan.project.typeInputs?.[k]||"미입력")).join(" / "),TYPE_IO[plan.project.type].outputs.join(" / "),i.inputNotes||"",i.outputNotes||""]})]}
